async function api(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',headers:data instanceof FormData?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:data instanceof FormData?data:JSON.stringify(data)});let d;try{d=await r.json()}catch{throw Error('The request could not be completed.')}if(!r.ok){if(r.status===401&&privatePage())location.href='/launchpad/login?next='+encodeURIComponent(location.pathname);throw Error(typeof d.detail==='string'?d.detail:'Please check the details and try again.')}return d;}
function toast(text,error=false){let n=$('#local-toast');if(!n){n=document.createElement('div');n.id='local-toast';n.setAttribute('role','status');document.body.append(n)}n.textContent=text;n.className=error?'is-error':'';clearTimeout(n.hide);n.hide=setTimeout(()=>n.remove(),5000)}
