function close(){const d=$('#local-dialog');if(d){if(d.dataset.aiDraft){const url=new URL(location.href);url.searchParams.delete('ai_draft');history.replaceState(null,'',url)}d.close();d.remove()}if(baseBody===null)$$('.v-overlay--active').forEach(n=>{n.classList.remove('v-overlay--active');n.style.display='none'});if(baseBody!==null){document.body.innerHTML=baseBody;baseBody=null;setup()}lastFocus?.focus?.();}
