const currentProject=el=>el?.closest('[data-project-id]')?.dataset.projectId||pathname.match(/\/app\/projects\/([^/]+)/)?.[1]||workspace?.tasks?.find(t=>t.id===taskId())?.project_id||document.body.dataset.projectId||workspace?.projects?.[0]?.id||'372311';
function isMyTask(t){return (t.assignee_ids||[]).includes(workspace.account.account_id);}
function taskAssigneeField(t){const people=new Map((workspace.people||[]).map(p=>[p.id,p]));for(const p of t?.assignees||[])if(!people.has(p.id))people.set(p.id,p);const direct=t?.direct_assignee_ids||t?.assignee_ids||[];return `<label>Assignee<select name=assignee_ids aria-label="Assignee" multiple><optgroup label="People">${[...people.values()].map(p=>`<option value="${esc(p.id)}" ${direct.includes(p.id)?'selected':''}>${esc(p.name)}${p.email?' ('+esc(p.email)+')':''}</option>`).join('')}</optgroup><optgroup label="Teams">${workspace.records.filter(r=>r.kind==='team').map(team=>`<option value="team:${esc(team.id)}" ${t?.assignee_team_ids?.includes(team.id)?'selected':''}>${esc(team.data.title)}</option>`).join('')}</optgroup></select></label>`;}
