function taskForm(t=null,parent='',defaults={}){let projects=workspace?.projects||[];if(!projects.length){projectForm();return}businessForm(t?'edit-task':'task',t?'Edit task':'Add a task',field('title','Task name','text',t?.title||defaults.title||'',true)+`<label>Description<textarea name="description">${esc(t?.description||'')}</textarea></label>`+select('priority','Priority',['None','Low','Medium','High'],t?.priority||'None')+select('stage','Stage',[...new Set(['Backlog','To do','In progress','Review','Done',...(workspace.records||[]).filter(r=>r.kind==='stage'&&r.parent===currentProject()).map(r=>r.data.title)])],t?.stage||defaults.stage||'Backlog')+field('tag','Tags','text',t?.tag||'')+field('start_date','Start date','date',t?.start_date||'')+field('due_date','Due date','date',t?.due_date||'')+taskAssigneeField(t)+`<input type="hidden" name="project_id" value="${esc(t?.project_id||defaults.project_id||currentProject())}">`+field('list_name','Task list','text',t?.list_name||defaults.list_name||document.body.dataset.tasklistName||'My List')+field('estimate','Estimated minutes','number',t?.estimate||0)+`<input type=hidden name=parent_id value="${esc(t?.parent_id||parent)}">`,`data-id="${esc(t?.id||'')}"`)}
