function aiWizard(kind,context=null){
 const saved=context||{kind,project_id:currentProject(),parent_id:'',list_name:'',overview:''};aiWizardContext=saved;
 if(kind==='project'){aiOverview(saved);return}
 const d=dialog('Add tasks with AI',`<p>BETA</p><button type=button data-ai-feedback>Feedback</button><h3>Smarter task creation starts here</h3><p>Choose a project to generate tasks instantly with AI.</p><form data-ai-select>${aiSelect('project_id','Select a project *',workspace.projects.map(p=>({id:p.id,title:p.name})),saved.project_id,true)}<div data-ai-project-fields></div><div class=local-error role=alert></div><div class=local-actions><button type=button data-action=close>Cancel</button><button type=submit class=local-primary>Next</button></div></form>`);
 const form=$('form',d),update=()=>{const pid=$('[name=project_id]',form).value;const lists=[...new Set([...workspace.tasks.filter(t=>t.project_id===pid).map(t=>t.list_name),...workspace.records.filter(r=>r.kind==='list'&&r.parent===pid).map(r=>r.data.title)])];$('[data-ai-project-fields]',form).innerHTML=aiSelect('list_name','Select a task list',lists.map(title=>({id:title,title})),saved.list_name)+aiSelect('parent_id','Select a parent task',workspace.tasks.filter(t=>t.project_id===pid),saved.parent_id)};
 update();$('[name=project_id]',form).addEventListener('change',update);$('[data-ai-feedback]',d).onclick=e=>{e.stopPropagation();businessForm('feedback','Feedback','<label>Feedback<textarea name=message required></textarea></label>')};
 form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();if(form.reportValidity())aiOverview({...saved,...Object.fromEntries(new FormData(form))})});
}
function aiOverview(context){
 aiWizardContext=context;const project=context.kind==='project';
 const promptTexts={"Basic Task Breakdown": "List the main tasks needed to complete a project. Break down each task into smaller, actionable subtasks if necessary.", "Phase-Based Task Planning": "Divide the project into key phases. For each phase, list the specific tasks required to complete it.", "Role-Specific Tasks": "Create a list of tasks for the project, grouped by team roles (e.g., design, development, marketing, etc.).", "Timeline-Ordered Tasks": "List the tasks for the project in the order they should be completed, from start to finish.", "SMART Tasks": "Generate 5-10 SMART (Specific, Measurable, Achievable, Relevant, Time-bound) tasks for the project"};const prompts=Object.keys(promptTexts);
 const d=dialog(project?'AI project wizard':'Add tasks with AI',`<button type=button data-ai-feedback>Feedback</button><h3>${project?'Let’s get started by adding your project details.':'Add your project details'}</h3><p>${project?'Type or upload a project overview. Include key information such as project name, client, end date, who’s on the team and key deliverables. You can also reference one of your own templates by name.':'Type or upload a project overview. Not sure where to start? Use a suggested prompt.'}</p><form data-ai-overview><label>Project overview<textarea name=overview placeholder="Add an overview to help AI build your project." rows=7 minlength=10 maxlength=12000 required>${esc(context.overview)}</textarea></label>${project?'':`<div class=local-actions>${prompts.map(p=>`<button type=button data-ai-prompt="${esc(p)}">${esc(p)}</button>`).join('')}</div>`}<button type=button data-ai-attach>Attach file</button><input type=file data-ai-file accept=".pdf,.txt,.md,.docx" hidden><p data-ai-attachment>${esc(context.attachment||'')}</p><p class=local-error role=alert></p><p data-ai-status role=status></p><div class=local-actions><button type=button data-action=close>Cancel</button>${project?'':'<button type=button data-ai-back>Back</button>'}<button type=submit class=local-primary>${project?'Start project wizard':'Generate tasks'}</button></div></form>`);
 const form=$('form',d),overview=$('[name=overview]',form);$('[data-ai-feedback]',d).onclick=e=>{e.stopPropagation();businessForm('feedback','Feedback','<label>Feedback<textarea name=message required></textarea></label>')};
 $('[data-ai-back]',d)?.addEventListener('click',e=>{e.stopPropagation();aiWizard('task',{...context,overview:overview.value})});
 for(const b of $$('[data-ai-prompt]',d))b.addEventListener('click',e=>{e.stopPropagation();overview.value=promptTexts[b.dataset.aiPrompt];overview.focus()});
 $('[data-ai-attach]',d).addEventListener('click',e=>{e.stopPropagation();$('[data-ai-file]',d).click()});
 $('[data-ai-file]',d).addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const fd=new FormData();fd.append('file',file);try{const result=await api('/api/ai/extract','POST',fd);const next=[overview.value.trim(),result.text].filter(Boolean).join('\n\n');if(next.length>12000)throw Error('Use an overview of up to 12,000 characters.');overview.value=next;context.attachment=result.name;$('[data-ai-attachment]',d).textContent=result.name;$('[data-ai-status]',d).textContent='Attachment text added to the overview.'}catch(error){errorAt(form,error)}finally{e.target.value=''}});
 form.addEventListener('submit',async e=>{e.preventDefault();e.stopPropagation();if(!form.reportValidity())return;const button=$('button[type=submit]',form);button.disabled=true;$('[data-ai-status]',form).textContent='Generating your draft…';try{const draft=await api('/api/ai/drafts','POST',{...context,overview:overview.value});if(d.isConnected)aiReview(draft);else toast('Draft saved. Open it from '+location.pathname+'?ai_draft='+draft.id)}catch(error){errorAt(form,error);$('[data-ai-status]',form).textContent=''}finally{button.disabled=false}});
}
function aiReview(draft){
 const d=dialog(draft.kind==='project'?'AI project wizard':'Add tasks with AI',`<h3>Review your draft</h3><p>Review and edit the generated plan before creating it.</p><form data-ai-review>${field('name','Project name','text',draft.payload.name,true)}<label>Description<textarea name=description maxlength=4000>${esc(draft.payload.description)}</textarea></label><div data-ai-tasks>${draft.payload.tasks.map((t,i)=>`<fieldset data-ai-task><legend>Task ${i+1}</legend>${field('title','Task name','text',t.title,true)}<label>Description<textarea name=description maxlength=4000>${esc(t.description)}</textarea></label>${select('priority','Priority',['None','Low','Medium','High'],t.priority)}${field('list_name','Task list','text',draft.context.list_name||t.list_name)}${field('due_date','Due date','date',t.due_date)}<button type=button data-ai-remove>Remove task</button></fieldset>`).join('')}</div><div class=local-error role=alert></div><p data-ai-status role=status></p><div class=local-actions><button type=button data-action=close>Cancel</button><button type=button data-ai-save>Save draft</button><button type=submit class=local-primary>${draft.result?'Open project':draft.kind==='project'?'Create project':'Add tasks'}</button></div></form>`);
 d.dataset.aiDraft=draft.id;const url=new URL(location.href);url.searchParams.set('ai_draft',draft.id);history.replaceState(null,'',url);const form=$('form',d);
 const payload=()=>({name:$('[name=name]',form).value,description:$('[name=description]',form).value,tasks:$$('[data-ai-task]',form).map(row=>Object.fromEntries($$('input,textarea,select',row).map(input=>[input.name,input.value])))});
 const save=async()=>{if(!form.reportValidity())return false;await api('/api/ai/drafts/'+draft.id,'PATCH',payload());return true};
 if(draft.result){for(const input of $$('input,textarea,select,[data-ai-remove],[data-ai-save]',form))input.disabled=true;$('[data-ai-status]',form).textContent='This draft has already been created.'}
 for(const b of $$('[data-ai-remove]',form))b.addEventListener('click',e=>{e.stopPropagation();if($$('[data-ai-task]',form).length===1){errorAt(form,'Keep at least one task.');return}b.closest('[data-ai-task]').remove()});
 $('[data-ai-save]',form).addEventListener('click',async e=>{e.stopPropagation();try{if(await save())$('[data-ai-status]',form).textContent='Draft saved.'}catch(error){errorAt(form,error)}});
 form.addEventListener('submit',async e=>{e.preventDefault();e.stopPropagation();const button=$('button[type=submit]',form);button.disabled=true;try{if(draft.result){location.href=draft.result.redirect;return}if(!await save())return;const result=await api('/api/ai/drafts/'+draft.id+'/confirm','POST',{});location.href=result.redirect}catch(error){errorAt(form,error)}finally{button.disabled=false}});
}
