  let html=/date arrives/.test(value)?field('run_at','At','time',rule.run_at||'09:00',true)+field('offset_days','Days before (negative) or after','number',rule.offset_days||0):['Task estimated time exceeds','Task progress exceeds'].includes(value)?field('threshold','Exceeds','number',rule.threshold||0,true):'';
