  if(value==='Task priority changes')html+=select('from_value','From',['Any','None','Low','Medium','High'],rule.from_value||'Any')+select('to_value','To',['Any','None','Low','Medium','High'],rule.to_value||'Any');
  if(value==='Task list changes'){const parent=$('[name=parent]',form).value,lists=new Map();for(const t of workspace.tasks){if(!parent||t.project_id===parent)lists.set(t.project_id+':'+encodeURIComponent(t.list_name),{project:t.project_id,name:t.list_name})}for(const r of workspace.records){if(r.kind==='list'&&(!parent||r.parent===parent))lists.set(r.parent+':'+encodeURIComponent(r.data.title),{project:r.parent,name:r.data.title})}const selected=(rule.task_list_project||parent)+':'+encodeURIComponent(rule.task_list||'');html+=`<label>Task list<select name=task_list aria-label="Task list" required><option value="">Select a task list</option>${[...lists].map(([id,list])=>option(id,(workspace.projects.find(p=>p.id===list.project)?.name||'')+' / '+list.name,selected)).join('')}</select></label>`;}
  if(value==='Every day')html+=`<fieldset><legend>On</legend>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((name,i)=>`<label><input type=checkbox data-daily-day value="${i}" ${(rule.weekdays?.length?rule.weekdays:[(new Date().getUTCDay()+6)%7]).includes(i)?'checked':''}>${name}</label>`).join('')}</fieldset>`+field('run_at','At','time',rule.run_at||'09:00',true)+'<small>UTC</small>';
  if(value==='Task inactive')html+=field('inactive_count','For','number',rule.inactive_count||1,true)+select('inactive_unit','Unit',['Day','Week'],rule.inactive_unit||'Day')+"<p>Existing tasks won't be affected by this trigger until they have been interacted with.</p>";
  if(value==='Task time logged')html+=`<label><input type=checkbox name=billable_only ${rule.billable_only?'checked':''}>Billable only</label>`;
  if(catalog.connection_triggers[value])html+='<label>Deal stage<select aria-label="Deal stage" disabled><option>Select pipeline and deal stage</option></select></label>'+connectionPanel(catalog.connection_triggers[value]);
  $('#local-automation-trigger-fields').innerHTML=html;if($('[name=inactive_count]',form))$('[name=inactive_count]',form).min='1';
