function widgetTitle(root){return $('[role=button] span',root)?.textContent.trim()||root?.getAttribute('name')||'Widget'}
function filterTimeLogs(rows,period){const now=new Date(),today=localToday();if(period==='Today')return rows.filter(r=>r.data.date===today);const start=new Date(now);start.setDate(now.getDate()-((now.getDay()+6)%7));const end=new Date(start);end.setDate(start.getDate()+7);const stamp=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return rows.filter(r=>r.data.date>=stamp(start)&&r.data.date<stamp(end))}
function timeWidgetName(root){if(!root)return '';return $('[name]',root)?.getAttribute('name')||root?.dataset.widgetType||widgetTitle(root)}
function taskTags(task){return [...new Set(String(task.tag||'').split(',').map(t=>t.trim()).filter(Boolean))]}
function createdInPeriod(task,filters){
 let period=filters.created_period||'Anytime';period=period.replace(/^Created /,'');period=period.charAt(0).toUpperCase()+period.slice(1);
 if(['All','Anytime'].includes(period))return true;if(!task.created_at)return false;
 const created=new Date(task.created_at),now=new Date();if(!Number.isFinite(created.getTime()))return false;
 let start=new Date(now.getFullYear(),now.getMonth(),now.getDate()),end;
 if(period==='Today'||period==='Yesterday'){if(period==='Yesterday')start.setDate(start.getDate()-1);end=new Date(start);end.setDate(end.getDate()+1)}
 else if(period==='This week'||period==='Last week'){start.setDate(start.getDate()-((start.getDay()+6)%7));if(period==='Last week')start.setDate(start.getDate()-7);end=new Date(start);end.setDate(end.getDate()+7)}
 else if(period==='This month'||period==='Last month'){start=new Date(now.getFullYear(),now.getMonth()-(period==='Last month'?1:0),1);end=new Date(start.getFullYear(),start.getMonth()+1,1)}
 else if(period==='Last 3 months'||period==='Last 6 months'){start=new Date(now.getFullYear(),now.getMonth()-(period==='Last 3 months'?3:6),1);end=new Date(now.getFullYear(),now.getMonth()+1,1)}
 else if(period==='Within the previous _ days'){const days=Number(filters.created_days);if(!Number.isInteger(days)||days<1)return false;end=new Date(start);end.setDate(end.getDate()+1);start.setDate(start.getDate()-days)}
 else if(period==='Custom'){if(!filters.created_after||!filters.created_before)return false;start=new Date(filters.created_after+'T00:00:00');end=new Date(filters.created_before+'T00:00:00');end.setDate(end.getDate()+1)}
 else return false;
 return created>=start&&created<end;
}
