function matchesTaskFilters(task,filters={}){
 const selected=key=>Array.isArray(filters[key])?filters[key]:[],tags=taskTags(task);
 if(filters.priority&&filters.priority!=='All'&&task.priority!==filters.priority)return false;
 if(filters.status==='Completed'&&!task.completed||filters.status==='Incomplete'&&task.completed)return false;
 if(filters.assigned==='me'&&!isMyTask(task))return false;
 if(selected('projects').length&&!selected('projects').includes(task.project_id))return false;
 if(selected('clients').length&&!selected('clients').includes(workspace.projects.find(p=>p.id===task.project_id)?.client_id))return false;
 if(filters.no_teams&&task.assignee_team_ids?.length)return false;
 if(selected('authors').length&&!selected('authors').includes(task.options?.created_by))return false;
 if(selected('tags').length&&!(filters.match_all_tags?selected('tags').every(t=>tags.includes(t)):selected('tags').some(t=>tags.includes(t))))return false;
 if(selected('exclude_tags').length&&(filters.match_all_excluded_tags?selected('exclude_tags').every(t=>tags.includes(t)):selected('exclude_tags').some(t=>tags.includes(t))))return false;
 if(filters.untagged&&tags.length||filters.no_subtasks&&task.parent_id)return false;
 if(filters.unblocked&&(task.options?.dependencies||[]).some(id=>{const dependency=workspace.tasks.find(t=>t.id===id);return !dependency||!dependency.completed}))return false;
 return createdInPeriod(task,filters);
}
