function dependenciesDialog(id){const t=workspace.tasks.find(t=>t.id===id);dialog('Dependencies',`<form data-business="dependencies" data-id="${esc(id)}"><p>Tasks that need to be completed before this task</p>${workspace.tasks.filter(x=>x.id!==id).map(x=>`<label><input type="checkbox" name="dependencies" value="${x.id}" ${(t.options?.dependencies||[]).includes(x.id)?'checked':''}>${esc(x.title)}</label>`).join('')}<button class="local-primary" type="submit">Save</button></form>`)}
function customFieldsDialog(id){const task=workspace.tasks.find(t=>t.id===id),fields=task.options?.custom_fields||{};dialog('Custom fields',`<p>${Object.keys(fields).length?'':'No custom fields have been added to this task'}</p><form data-business="custom-field" data-id="${id}">${field('field_name','Field name','text','',true)}${field('field_value','Value','text','',true)}<button type=submit class=local-primary>Add custom field</button></form><div class=local-records>${Object.entries(fields).map(([key,value])=>`<article><strong>${esc(key)}</strong><p>${esc(value)}</p><button data-remove-custom-field="${esc(key)}" data-task="${id}">Delete</button></article>`).join('')}</div>`)}
function transferDialog(id){businessForm('transfer','Move or copy task',select('action','Action',['Move','Copy'],'Move')+`<label>Project<select name=project_id>${workspace.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>`+field('list_name','Task list','text',workspace.tasks.find(t=>t.id===id)?.list_name||'My List'),`data-id="${id}"`)}
async function manageAutomations(){const deliveries=await api('/api/automations/http-deliveries');const rules=workspace.records.filter(r=>r.kind==='automation');dialog('Manage automations',`<button data-action="new-automation">Create automation</button><div class="local-records">${rules.length?rules.map(r=>`<article><strong>${esc(r.data.title)}</strong><p>When ${esc(r.data.trigger)}, ${esc(r.data.effect)}</p><button data-toggle-rule="${r.id}">${r.data.enabled===false?'Enable':'Disable'}</button><button data-action="edit-record" data-record="${r.id}">Edit</button><button data-delete-rule="${r.id}">Delete</button></article>`).join(''):'<p>No automations yet</p>'}</div>${deliveries.length?`<section><h3>HTTP requests</h3><button data-refresh-http-history>Refresh</button>${deliveries.map(r=>`<div data-http-delivery="${r.id}"><strong>${esc(r.method)} ${esc(r.url)}</strong><p>${esc(r.state)}${r.status_code?' · HTTP '+r.status_code:''} · ${r.attempts} attempt${r.attempts===1?'':'s'}</p>${r.error?`<p>${esc(r.error)}</p>`:''}${r.response?`<pre>${esc(r.response)}</pre>`:''}${['failed','blocked','unknown'].includes(r.state)?`<button data-retry-http="${r.id}">Retry request</button>`:''}</div>`).join('')}</section>`:''}`)}
const availableTaskColumns=['Progress','Estimated time','Client','Parent task','Start date','Stage','Repeats','Privacy','Created by','Completed by','Date created','Reminders','Task ID','Desk tickets'];
function configureColumns(){const active=[...new Set($$('main [role=columnheader],main th').map(n=>(n.getAttribute('data-column-name')||n.textContent).trim()).filter(Boolean))];if(!active.length)return;const extra=pathname.endsWith('/tasks/table')?availableTaskColumns.filter(n=>!active.includes(n)):[];const saved=workspace.preferences['columns:'+pathname]||{};dialog('Add/remove columns',`<form data-business="columns">${[...active,...extra].map((n,i)=>`${i===active.length?'<h3>Available columns</h3>':''}<label><input type=checkbox name="col${i}" data-column="${esc(n)}" ${(active.includes(n)?saved[n]!==false:saved[n]===true)?'checked':''}>${esc(n)}</label>`).join('')}<button class=local-primary type=submit>Save shared view</button></form>`)}
function restoreTablePreferences(){const saved=workspace.preferences['columns:'+pathname]||{};for(const header of $$('main [role=columnheader],main th')){const label=header.getAttribute('data-column-name')||header.textContent.trim();header.setAttribute('data-column-name',label);const idx=[...header.parentElement.children].indexOf(header),table=header.closest('table,[role=table],[role=grid]');if(!table)continue;for(const row of $$('tr,[role=row]',table)){if(row.children.length>1&&row.children[idx])row.children[idx].hidden=saved[label]===false;}}}
let taskTableTemplate=null;
function renderTaskTable(){if(!pathname.endsWith('/tasks/table'))return;const table=$('main table'),first=table&&($('[data-task-id]',table)||$('#local-task-table-template')?.content.firstElementChild);if(!table||(!first&&!taskTableTemplate))return;if(!taskTableTemplate)taskTableTemplate=first.cloneNode(true);const parent=$('tbody[data-local-tasks]',table)||first?.parentElement,head=$('thead tr',table),prefs=workspace.preferences['columns:'+pathname]||{};for(const h of $$('[data-extra-column]',head))h.remove();const extra=availableTaskColumns.filter(n=>prefs[n]===true);for(const name of extra){const th=document.createElement('th');th.dataset.extraColumn=name;th.dataset.columnName=name;th.textContent=name;th.className=head.firstElementChild.className;head.append(th)}const all=workspace.tasks.filter(t=>t.project_id===currentProject());for(const row of $$('[data-task-id]',table))row.remove();const anchor=$$('tr',parent).find(r=>r.textContent.includes('Add a task'));
for(const t of all){const row=taskTableTemplate.cloneNode(true);row.dataset.taskId=t.id;row.setAttribute('data-item-selection-task-id',t.id);const minutes=workspace.records.filter(r=>r.kind==='time'&&r.parent===t.id).reduce((sum,r)=>sum+Number(r.data.minutes||0),0);const base=[`<button aria-label="${t.completed?'Mark incomplete':'Mark complete'}">${t.completed?'✓':'○'}</button><a data-identifier="task-list-item-name" href="/app/tasks/${t.id}">${esc(t.title)}</a>`,`<button aria-label="Assign this task">${esc(t.assignee||'Assign')}</button>`,`<button aria-label="Set dates">${esc(t.due_date||'Add date')}</button>`,`<button aria-label="${esc(t.priority)}">${esc(t.priority)}</button>`,`<button aria-label="Log time">${minutes?minutes+' min':'Log time'}</button><button aria-label="Start timer">▶</button>`,`<button aria-label="Add tags">${esc(t.tag||'Add tags')}</button>`,`<button aria-label="Update task list">${esc(t.list_name)}</button>`];base.forEach((value,i)=>{if(row.children[i])row.children[i].innerHTML=value});for(const name of extra){let value={'Progress':(t.options?.progress||0)+'%','Estimated time':t.estimate+' min','Parent task':workspace.tasks.find(p=>p.id===t.parent_id)?.title||'','Start date':t.start_date||'','Stage':t.stage,'Repeats':t.options?.repeat||'Does not repeat','Privacy':t.options?.privacy||'Everyone on project','Task ID':t.id,'Created by':t.options?.created_by===workspace.account.account_id?workspace.account.display_name:'','Date created':t.created_at||'','Completed by':t.options?.completed_by===workspace.account.account_id?workspace.account.display_name:''}[name]??'';const td=document.createElement('td');td.className=row.firstElementChild.className;td.dataset.extraColumn=name;td.textContent=value||'—';row.append(td)}parent.insertBefore(row,anchor||null)}const widths=['minmax(260px,2fr)','130px','140px','120px','140px','150px','150px','20px','40px',...extra.map(()=> '150px')].filter((_,i)=>prefs[head.children[i]?.dataset.columnName||head.children[i]?.textContent.trim()]!==false);table.style.setProperty('--lsc-table-grid-cols',widths.join(' '));const count=$('thead [data-identifier*=count]',table);if(count)count.textContent=all.length;restoreTablePreferences();}

function applyTaskView(){if(!workspace)return;const filters=workspace.preferences['filter:'+pathname]||{},order=workspace.preferences['sort:'+pathname]||'';for(const row of $$('[data-task-id]')){const t=workspace.tasks.find(t=>t.id===row.dataset.taskId);if(!t)continue;const wf=workspace.preferences['widget-filter:'+widgetKey(row)]||{},f=widgetKey(row)?wf:filters;row.hidden=!matchesTaskFilters(t,f)||(pathname.startsWith('/app/projects/')&&t.project_id!==currentProject());}if(order&&!taskId()){const groups=new Map();for(const row of $$('[data-task-id]')){const list=groups.get(row.parentElement)||[];list.push(row);groups.set(row.parentElement,list)}for(const [parent,rows] of groups){rows.sort((a,b)=>{const x=workspace.tasks.find(t=>t.id===a.dataset.taskId),y=workspace.tasks.find(t=>t.id===b.dataset.taskId);if(!x||!y)return 0;if(order==='Priority')return ['High','Medium','Low','None'].indexOf(x.priority)-['High','Medium','Low','None'].indexOf(y.priority);if(order==='Due date')return (x.due_date||'9999').localeCompare(y.due_date||'9999');return x.title.localeCompare(y.title)*(order==='Name descending'?-1:1)});for(const row of rows)parent.append(row)}}restoreTablePreferences();}

