async function searchDialog(){dialog('Search',`<label>Search<input id="local-search" placeholder="Search projects, tasks and pages" autofocus></label><div id="local-search-results"></div>`);if(privatePage())await refresh();$('#local-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();const items=privatePage()?[...workspace.projects.map(p=>({title:p.name,url:'/app/projects/'+p.id+'/tasks/list'})),...workspace.tasks.map(t=>({title:t.title,url:'/app/tasks/'+t.id})),...workspace.records.filter(r=>!['automation','invitation','preference'].includes(r.kind)).map(r=>({title:r.data.title||r.data.name||r.data.text||r.data.description||r.kind,url:({'client':'/app/clients/clients','role':'/app/people/roles','skill':'/app/people/skills','team':'/app/people/teams','notification':'/app/inbox'}[r.kind])|| (workspace.tasks.some(t=>t.id===r.parent)?'/app/tasks/'+r.parent:'/app/projects/'+(r.parent||currentProject())+'/'+({message:'messages',notebook:'notebooks',file:'files',link:'links',time:'time',milestone:'milestones',event:'calendar',risk:'risks',form:'forms',budget:'finance/budgets',invoice:'finance/invoices'}[r.kind]||'tasks/list')+'#record-'+r.id)}))]:$$('a[href]').map(a=>({title:a.textContent.trim(),url:a.getAttribute('href')}));$('#local-search-results').innerHTML=items.filter(x=>x.title.toLowerCase().includes(q)&&x.title).slice(0,30).map(x=>`<a href="${esc(x.url)}">${esc(x.title)}</a>`).join('')||'<p>No results found</p>'});$('#local-search').dispatchEvent(new Event('input'));}
async function upload(){const input=document.createElement('input');input.type='file';input.onchange=async()=>{if(!input.files[0])return;const data=new FormData();data.append('file',input.files[0]);data.append('parent',taskId()||currentProject());try{await api('/api/files','POST',data);await refresh();toast('File uploaded')}catch(e){toast(e.message,true)}};input.click()}
