if(el.dataset.deleteReminder){await api('/api/reminders/'+el.dataset.deleteReminder,'DELETE');await remindersDialog(el.dataset.task);return}
if(el.dataset.removeCustomField){const id=el.dataset.task,fields={...workspace.tasks.find(t=>t.id===id).options.custom_fields};delete fields[el.dataset.removeCustomField];await api('/api/tasks/'+id+'/options','PUT',{custom_fields:fields});await refresh();customFieldsDialog(id);return}
if(el.hasAttribute('data-refresh-http-history')){e.preventDefault();await manageAutomations();return}if(el.dataset.retryHttp){e.preventDefault();await api('/api/automations/http-deliveries/'+el.dataset.retryHttp+'/retry','POST',{});await manageAutomations();return}
if(el.dataset.toggleRule){const r=workspace.records.find(r=>r.id===el.dataset.toggleRule);await api('/api/records/'+r.id,'PATCH',{enabled:r.data.enabled===false});await refresh();manageAutomations();return}
