function descriptionTooltip(el){$('#local-description-tooltip')?.remove();if(!el)return;const text=el.getAttribute('aria-description');if(!text)return;const tip=document.createElement('div');tip.id='local-description-tooltip';tip.setAttribute('role','tooltip');tip.textContent=text;document.body.append(tip);const rect=el.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(rect.left,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.min(rect.bottom+6,innerHeight-tip.offsetHeight-8)+'px';}
